/// <summary>
/// Constructs the reference identities used to populate the <c>METOrderExtractScreen</c> form.
/// </summary>
public class METOrderExtractScreenProcessor
{
    METOrderExtractScreenTmp                metOrderExtractScreenTmp;
    MEtOrderExtractScreenParameters         metOrderExtractScreenParameters;
    SalesTable                              salesTable;
    SalesLine                               salesLine;
    SalesLine                               salesLineIns;
    MetItemSiteSettingsSetup                itemSiteSettings;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSite;
    METWHSPhysDimUOMSite                    metWHSPhysDimUOMSiteJoin;
    InventDim                               inventDim;
    METOrderExtractScreenUOMView            uomView;
    METOrderExtractScreenPhysDimView        physDimView;
    WHSPhysDimUOM                           whsPhysDimUOM;
    WHSPhysDimUOM                           whsPhysDimUOMJoin;
    METOrderExtractScreenUOMViewTmp         uomViewTmp;
    ReqItemTable                            reqItemTable;
    METReqItemTable                         metReqItemTable;        
    InventDim                               inventDimReq;

    Factor                                  factor;
    InventQty                               cases;
    InventSiteId                            site;
    InventLocationId                        warehouse;
    METRoute                                route;
    SalesShippingDateConfirmed              shippingDate;
    METFilterCodeone                        category;
    Volume                                  totalVolume;

}

